"use client";
import { AppShell } from "../ui/app-shell";
import { usePlayerData } from "../../lib/use-player-data";
export default function Performance() { const { aggregates } = usePlayerData(); const total = aggregates.reduce((s,r)=>s+r.opportunities,0); const rows = aggregates.map((r)=>{const frequency=total?r.opportunities/total:0;const success=r.opportunities?r.successes/r.opportunities:0;const evidence=Math.min(1,r.opportunities/5);const priority=frequency*(1-success)*evidence;return{...r,frequency,success,evidence,priority}}).sort((a,b)=>b.priority-a.priority); return <AppShell active="performance"><header className="page-heading"><div><p className="eyebrow">Performance engine</p><h1>Priorities, weighted by play.</h1><p>Priority = frequency × failure rate × evidence confidence. Rare shots stay visible without overwhelming the practice plan.</p></div></header><section className="analysis-table"><div className="analysis-row analysis-five header"><span>Shot band</span><span>Opportunities</span><span>Frequency</span><span>Success</span><span>Priority</span></div>{rows.map((r,i)=><div className="analysis-row analysis-five" key={r.shot_band}><strong>{r.shot_band}</strong><span>{r.opportunities}</span><span>{Math.round(r.frequency*100)}%</span><span>{Math.round(r.success*100)}%</span><span className={`status ${i===0?"high":i<3?"medium":"low-evidence"}`}>{i===0?"High":i<3?"Develop":"Monitor"} · {Math.round(r.priority*100)}</span></div>)}{!rows.length&&<div className="empty-state compact"><h2>No performance data yet</h2><p>Save a Quick Round or detailed round to populate this analysis.</p></div>}</section></AppShell>; }
